/**
 * Structured JSON logger for Cloud Logging.
 * Outputs JSON lines compatible with Google Cloud Logging severity levels.
 */

export type LogSeverity = 'DEBUG' | 'INFO' | 'WARNING' | 'ERROR' | 'CRITICAL'

export interface LogEntry {
  severity: LogSeverity
  message: string
  roomId?: string
  roomType?: string
  playerId?: string
  [key: string]: unknown
}

export class Logger {
  private readonly context: Record<string, unknown>

  constructor(context?: { roomId?: string; roomType?: string }) {
    this.context = context ?? {}
  }

  debug(message: string, data?: Record<string, unknown>): void {
    this.write('DEBUG', message, data)
  }

  info(message: string, data?: Record<string, unknown>): void {
    this.write('INFO', message, data)
  }

  warn(message: string, data?: Record<string, unknown>): void {
    this.write('WARNING', message, data)
  }

  error(message: string, data?: Record<string, unknown>): void {
    this.write('ERROR', message, data)
  }

  critical(message: string, data?: Record<string, unknown>): void {
    this.write('CRITICAL', message, data)
  }

  /**
   * Create a child logger with additional context fields.
   */
  child(extra: Record<string, unknown>): Logger {
    const child = new Logger()
    Object.assign((child as any).context, this.context, extra)
    return child
  }

  private write(
    severity: LogSeverity,
    message: string,
    data?: Record<string, unknown>,
  ): void {
    const entry: LogEntry = {
      severity,
      message,
      timestamp: new Date().toISOString(),
      ...this.context,
      ...data,
    }
    // Cloud Logging parses JSON from stdout automatically
    const line = JSON.stringify(entry)
    if (severity === 'ERROR' || severity === 'CRITICAL') {
      console.error(line)
    } else {
      console.log(line)
    }
  }
}
