/**
 * Reusable server-authoritative turn loop (Req 21 / AC-21).
 *
 * Owns turn order, the current turn, and server-side move validation/advance for
 * turn-based `GameRoom`s. The room is the single authority: only the current
 * player's move is accepted, an out-of-turn move throws, and the turn advances
 * server-side. Snapshot/restore lets a persistent room survive freeze + resume.
 *
 * This is pure logic (no I/O); a `GameRoom` instantiates one and calls
 * `submitTurn` from `onGameMessage`, broadcasting the resulting state.
 */

export class TurnError extends Error {
  constructor(
    public readonly code: 'NOT_YOUR_TURN' | 'NOT_IN_GAME' | 'EMPTY_ORDER',
    message: string,
  ) {
    super(message)
    this.name = 'TurnError'
  }
}

export interface TurnManagerSnapshot {
  order: string[]
  currentIndex: number
  /** Monotonic count of completed turns; useful for round detection. */
  turnNumber: number
}

export class TurnManager {
  private order: string[]
  private currentIndex: number
  private turnNumber: number

  constructor(order: ReadonlyArray<string> = [], startIndex = 0) {
    this.order = [...order]
    if (this.order.length > 0 && (startIndex < 0 || startIndex >= this.order.length)) {
      throw new TurnError('EMPTY_ORDER', `startIndex ${startIndex} out of range for ${this.order.length} players`)
    }
    this.currentIndex = this.order.length === 0 ? 0 : startIndex
    this.turnNumber = 0
  }

  static restore(snapshot: TurnManagerSnapshot): TurnManager {
    const tm = new TurnManager(snapshot.order, snapshot.order.length === 0 ? 0 : snapshot.currentIndex)
    tm.turnNumber = snapshot.turnNumber
    return tm
  }

  get players(): ReadonlyArray<string> {
    return this.order
  }

  /** The player whose turn it is, or null when no players are in the order. */
  get currentPlayerId(): string | null {
    return this.order.length === 0 ? null : this.order[this.currentIndex]
  }

  /** Number of turns advanced so far (0 before the first move completes). */
  get turn(): number {
    return this.turnNumber
  }

  isCurrentTurn(playerId: string): boolean {
    return this.currentPlayerId === playerId
  }

  /** Throw unless it is `playerId`'s turn. Does not advance. */
  assertTurn(playerId: string): void {
    if (this.order.length === 0) {
      throw new TurnError('EMPTY_ORDER', 'No players in the turn order')
    }
    if (!this.order.includes(playerId)) {
      throw new TurnError('NOT_IN_GAME', `Player ${playerId} is not in the turn order`)
    }
    if (this.currentPlayerId !== playerId) {
      throw new TurnError('NOT_YOUR_TURN', `It is ${this.currentPlayerId}'s turn, not ${playerId}'s`)
    }
  }

  /**
   * Validate it is `playerId`'s turn and advance to the next player.
   * Throws {@link TurnError} (no state change) for an out-of-turn or unknown player.
   * Returns the new current player id.
   */
  submitTurn(playerId: string): string {
    this.assertTurn(playerId)
    return this.advance()
  }

  /** Advance to the next player without validation (e.g. timeout/skip). */
  advance(): string {
    if (this.order.length === 0) {
      throw new TurnError('EMPTY_ORDER', 'Cannot advance an empty turn order')
    }
    this.currentIndex = (this.currentIndex + 1) % this.order.length
    this.turnNumber += 1
    return this.order[this.currentIndex]
  }

  /** Add a player to the end of the turn order (no-op if already present). */
  addPlayer(playerId: string): void {
    if (!this.order.includes(playerId)) {
      this.order.push(playerId)
    }
  }

  /**
   * Remove a player, keeping the current turn pointing at the same logical
   * player where possible. Removing the current player advances to the next.
   */
  removePlayer(playerId: string): void {
    const idx = this.order.indexOf(playerId)
    if (idx === -1) return

    const wasCurrent = idx === this.currentIndex
    this.order.splice(idx, 1)

    if (this.order.length === 0) {
      this.currentIndex = 0
      return
    }
    if (idx < this.currentIndex) {
      // The current player shifted left by one.
      this.currentIndex -= 1
    } else if (wasCurrent) {
      // Index now points at the player who followed; wrap if we removed the tail.
      this.currentIndex %= this.order.length
    }
  }

  snapshot(): TurnManagerSnapshot {
    return { order: [...this.order], currentIndex: this.currentIndex, turnNumber: this.turnNumber }
  }
}
