/**
 * Platform season/expiry primitive (Req 23 / AC-23).
 *
 * A game-agnostic schedule of seasons. Each season is a named, time-windowed
 * period. The schedule answers, for any clock:
 *   - which seasons are active (supporting overlapping windows),
 *   - which single season is "current" (the newest active one),
 *   - whether a given season key is live (the server-authoritative join gate),
 *   - the persistent-room id key to use for a season.
 *
 * It is the single source of truth for season logic. Because the GameRoom
 * bundle imports the SDK and runs server-side in the room worker, the same
 * primitive enforces seasons authoritatively on the server and computes the
 * active set on the client — no duplicated season logic.
 */
export interface SeasonDefinition {
  /** Stable, unique key. Derives the persistent-room id key — never reuse. */
  key: string;
  /** Inclusive start, epoch ms. */
  startsAt: number;
  /** Exclusive end, epoch ms. Omit for an open-ended (never-expiring) season. */
  endsAt?: number;
}

export interface RecurringSeasonsOptions {
  /** Epoch ms at which season index 0 begins. */
  anchorMs: number;
  /** Length of each season, ms. */
  durationMs: number;
  /** How many seasons to generate. */
  count: number;
  /** Key for season index n. Defaults to `season-${n}`. */
  key?: (n: number) => string;
  /**
   * Overlap, ms: each season after the first starts this much earlier than the
   * previous one ends, creating a preview/grace window where both are active.
   * Defaults to 0 (back-to-back, no overlap).
   */
  overlapMs?: number;
}

export class SeasonSchedule {
  private readonly seasons: readonly SeasonDefinition[];

  constructor(seasons: SeasonDefinition[]) {
    const seen = new Set<string>();
    for (const s of seasons) {
      if (seen.has(s.key)) {
        throw new Error(`SeasonSchedule: duplicate season key "${s.key}"`);
      }
      seen.add(s.key);
      if (s.endsAt !== undefined && s.endsAt <= s.startsAt) {
        throw new Error(`SeasonSchedule: season "${s.key}" ends at or before it starts`);
      }
    }
    this.seasons = [...seasons].sort((a, b) => a.startsAt - b.startsAt);
  }

  /**
   * Build a recurring schedule with automatic rollover and key derivation.
   * Season n occupies `[anchorMs + n*durationMs, anchorMs + (n+1)*durationMs)`,
   * with each season after the first pulled `overlapMs` earlier at its start.
   */
  static recurring(opts: RecurringSeasonsOptions): SeasonSchedule {
    if (opts.durationMs <= 0) throw new Error('SeasonSchedule.recurring: durationMs must be > 0');
    if (opts.count < 0) throw new Error('SeasonSchedule.recurring: count must be >= 0');
    const keyFn = opts.key ?? ((n: number) => `season-${n}`);
    const overlapMs = opts.overlapMs ?? 0;
    const seasons: SeasonDefinition[] = [];
    for (let n = 0; n < opts.count; n += 1) {
      const start = opts.anchorMs + n * opts.durationMs;
      seasons.push({
        key: keyFn(n),
        startsAt: n > 0 ? start - overlapMs : start,
        endsAt: opts.anchorMs + (n + 1) * opts.durationMs,
      });
    }
    return new SeasonSchedule(seasons);
  }

  /** All declared seasons, ordered by start. */
  all(): readonly SeasonDefinition[] {
    return this.seasons;
  }

  /** Seasons live at `nowMs` (startsAt <= now < endsAt). Multiple if windows overlap. */
  activeSeasons(nowMs: number): SeasonDefinition[] {
    return this.seasons.filter(
      (s) => nowMs >= s.startsAt && (s.endsAt === undefined || nowMs < s.endsAt),
    );
  }

  /** Active season keys at `nowMs`. */
  activeSeasonKeys(nowMs: number): string[] {
    return this.activeSeasons(nowMs).map((s) => s.key);
  }

  /**
   * The single current season: the active season with the latest start (the
   * newest one when windows overlap). Throws when none is active — a player must
   * always resolve to a concrete season (fail fast, no silent fallback).
   */
  currentSeason(nowMs: number): SeasonDefinition {
    const active = this.activeSeasons(nowMs);
    if (active.length === 0) {
      throw new Error(`SeasonSchedule: no active season at ${nowMs}`);
    }
    return active.reduce((latest, s) => (s.startsAt > latest.startsAt ? s : latest));
  }

  /** Whether `seasonKey` is declared and live at `nowMs` — the join gate. */
  isActive(seasonKey: string, nowMs: number): boolean {
    return this.activeSeasons(nowMs).some((s) => s.key === seasonKey);
  }

  /**
   * The persistent-room id key for a season. The platform feeds this into the
   * persistent room id (`persistent:<game>:<type>:<key>`). Identity by default —
   * exposed as a method so any future namespacing has one home.
   */
  roomKey(seasonKey: string): string {
    return seasonKey;
  }
}
