/**
 * Managed timer system for GameRoom with named handles and auto-cleanup.
 * Timers are serializable for crash recovery.
 */

interface ActiveTimer {
  name: string
  intervalMs: number
  repeat: boolean
  startedAt: number
  handle: ReturnType<typeof setTimeout> | ReturnType<typeof setInterval>
  callback: () => void
}

/**
 * Serializable representation of a Clock's timers, for crash recovery.
 */
export interface ClockSnapshot {
  timers: Array<{
    name: string
    intervalMs: number
    repeat: boolean
    startedAt: number
    remainingMs: number
  }>
}

export class Clock {
  private timers = new Map<string, ActiveTimer>()
  private disposed = false

  /**
   * Start a repeating interval timer.
   * If a timer with the same name exists, it is replaced.
   */
  setInterval(name: string, callback: () => void, intervalMs: number): void {
    this.assertNotDisposed()
    this.clear(name)
    const handle = setInterval(() => {
      if (!this.disposed) callback()
    }, intervalMs)
    this.timers.set(name, {
      name,
      intervalMs,
      repeat: true,
      startedAt: Date.now(),
      handle,
      callback,
    })
  }

  /**
   * Start a one-shot timeout timer.
   * If a timer with the same name exists, it is replaced.
   */
  setTimeout(name: string, callback: () => void, delayMs: number): void {
    this.assertNotDisposed()
    this.clear(name)
    const handle = setTimeout(() => {
      this.timers.delete(name)
      if (!this.disposed) callback()
    }, delayMs)
    this.timers.set(name, {
      name,
      intervalMs: delayMs,
      repeat: false,
      startedAt: Date.now(),
      handle,
      callback,
    })
  }

  /**
   * Clear a specific timer by name.
   */
  clear(name: string): void {
    const timer = this.timers.get(name)
    if (timer) {
      if (timer.repeat) {
        clearInterval(timer.handle)
      } else {
        clearTimeout(timer.handle)
      }
      this.timers.delete(name)
    }
  }

  /**
   * Check if a timer with the given name is active.
   */
  has(name: string): boolean {
    return this.timers.has(name)
  }

  /**
   * Serialize all active timers for crash recovery.
   */
  snapshot(): ClockSnapshot {
    const now = Date.now()
    const timers: ClockSnapshot['timers'] = []
    for (const timer of this.timers.values()) {
      const elapsed = now - timer.startedAt
      const remainingMs = timer.repeat
        ? timer.intervalMs - (elapsed % timer.intervalMs)
        : Math.max(0, timer.intervalMs - elapsed)
      timers.push({
        name: timer.name,
        intervalMs: timer.intervalMs,
        repeat: timer.repeat,
        startedAt: timer.startedAt,
        remainingMs,
      })
    }
    return { timers }
  }

  /**
   * Adjust currently registered timers to match a persisted snapshot's timings.
   * For each timer in the snapshot that matches a currently registered timer by
   * name, the timer is re-scheduled with the snapshot's remaining time.
   * Called automatically by GameRoom after onRestore/onMigrate.
   * @internal
   */
  restoreTimings(snap: ClockSnapshot): void {
    this.assertNotDisposed()
    for (const t of snap.timers) {
      const existing = this.timers.get(t.name)
      if (!existing) continue // timer not re-registered by game, skip

      // Clear the freshly registered timer
      if (existing.repeat) {
        clearInterval(existing.handle)
      } else {
        clearTimeout(existing.handle)
      }

      const cb = existing.callback

      if (t.repeat) {
        // Fire after remaining time, then resume normal interval
        const handle = setTimeout(() => {
          if (this.disposed) return
          cb()
          this.setInterval(t.name, cb, t.intervalMs)
        }, t.remainingMs)
        this.timers.set(t.name, {
          name: t.name,
          intervalMs: t.intervalMs,
          repeat: true,
          startedAt: Date.now(),
          handle,
          callback: cb,
        })
      } else {
        // Re-register timeout with remaining time
        this.timers.delete(t.name)
        this.setTimeout(t.name, cb, t.remainingMs)
      }
    }
  }

  /**
   * Clear all timers and mark the clock as disposed.
   */
  dispose(): void {
    this.disposed = true
    for (const timer of this.timers.values()) {
      if (timer.repeat) {
        clearInterval(timer.handle)
      } else {
        clearTimeout(timer.handle)
      }
    }
    this.timers.clear()
  }

  private assertNotDisposed(): void {
    if (this.disposed) {
      throw new Error('Clock has been disposed')
    }
  }
}
