/** Error thrown when a platform service call fails (bridge unavailable, timeout, or HTTP error). */
export class ServiceError extends Error {
  constructor(
    public readonly code: string,
    message: string,
  ) {
    super(message)
    this.name = 'ServiceError'
  }
}

export interface NotificationSendRequest {
  /** Profile IDs to notify (offline push via inbox broker). */
  recipientProfileIds: string[]
  /** Template key resolved against the game's inbox.templates config. */
  template: string
  /** Substitution params for the template. */
  params?: Record<string, string | number>
  /** Arbitrary data delivered with the push (e.g. deep-link context). */
  data?: Record<string, unknown>
  /** Used if the template is missing. */
  fallbackTitle?: string
  fallbackBody?: string
}

export interface LeaderboardService {
  submitScore(leaderboardId: string, score: number, metadata?: Record<string, unknown>): Promise<void>
  getTop(leaderboardId: string, limit: number): Promise<Array<{ profileId: string; score: number; rank: number }>>
}

export interface UgcService {
  get(ugcId: string): Promise<Record<string, unknown> | null>
  recordUse(ugcId: string): Promise<void>
}

export interface SimulationService {
  // Realtime rooms have multiple members; every call is made on behalf of an
  // acting player. The bridge maps the room's playerId → profileId (mp-room-server
  // knows the profileId per connection). This resolves the V1 "profile-scoped
  // state within a room" model to a specific member.
  getState(playerId: string): Promise<Record<string, unknown>>
  executeRecipe(playerId: string, recipeId: string, input?: Record<string, unknown>): Promise<Record<string, unknown>>
  getActiveRuns(playerId: string): Promise<Array<Record<string, unknown>>>
  getAvailableRecipes(playerId: string): Promise<Array<Record<string, unknown>>>
  /**
   * Authoritatively grant a `meta`-tagged (cross-season, t3) entity to a current
   * member's player-global simulation. The platform rejects the call for a
   * non-member and rejects entities that are not `meta`-tagged (a season-scoped
   * entity must be earned in-season, not granted globally). Use for season-end
   * permanence awards (e.g. `commander_vp`).
   */
  grantMeta(playerId: string, entityId: string, amount: number): Promise<void>
}

export interface EconomyClaimResult {
  /** How much was actually granted (0 ≤ granted ≤ requested). */
  granted: number
  /** Pool quantity remaining after the operation. */
  remaining: number
}

/**
 * Server-authoritative shared-economy pools (Req 10). Pools are scoped to the
 * calling room/world (the platform namespaces them by roomId, so a room can only
 * touch its own pools — and for a persistent season room that makes them
 * per-season by construction). Calls originate from the authoritative GameRoom
 * worker, never from client input, so a client cannot forge an economic outcome
 * (AC-6). Settlement never over-allocates a finite pool (AC-10) and concurrent
 * contributions never lose updates (AC-4).
 */
export interface EconomyService {
  /**
   * Claim up to `amount` from a finite shared pool. `allowPartial` (default
   * true) grants `min(amount, remaining)`; `false` is all-or-nothing.
   */
  claim(poolId: string, amount: number, opts?: { allowPartial?: boolean }): Promise<EconomyClaimResult>
  /** Add `amount` to a shared pool (replenish / contribute). */
  contribute(poolId: string, amount: number): Promise<{ remaining: number }>
  /** Current remaining quantity of a pool. */
  remaining(poolId: string): Promise<number>
}

export interface PlatformServices {
  notifications: { send(request: NotificationSendRequest): Promise<void> }
  leaderboard: LeaderboardService
  ugc: UgcService
  simulation: SimulationService
  economy: EconomyService
  getGameConfig(): Promise<Record<string, unknown>>
}
